package com.nextaicommerce.platform.fba;
import java.time.*;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Repository;import org.springframework.transaction.annotation.Transactional;import tools.jackson.databind.ObjectMapper;
import static com.nextaicommerce.platform.fba.FbaReplenishmentMath.*;
@Repository
public class FbaReplenishmentSettings {
 private final JdbcTemplate jdbc;private final ObjectMapper json;public FbaReplenishmentSettings(JdbcTemplate jdbc,ObjectMapper json){this.jdbc=jdbc;this.json=json;}
 void scope(UUID tenant){jdbc.queryForObject("SELECT set_config('app.tenant_id',?,true)",String.class,tenant.toString());}
 @Transactional(readOnly=true) public List<Map<String,Object>> policies(UUID tenant){scope(tenant);return decoded(jdbc.queryForList("SELECT scope_key,configuration::text configuration,revision,updated_at FROM fba_replenishment_policies WHERE tenant_id=? ORDER BY scope_key",tenant));}
 List<Map<String,Object>> decoded(List<Map<String,Object>> rows){for(var row:rows)row.put("configuration",json.readValue(row.get("configuration").toString(),Map.class));return rows;}
 public record PolicyChange(String scope,long revision,Policy policy){}
 @Transactional public void savePolicy(UUID tenant,UUID connection,String email,PolicyChange change){scope(tenant);if(change==null||change.policy()==null||change.scope()==null||!(change.scope().equals("ACCOUNT")||change.scope().startsWith("BRAND:")&&change.scope().length()>6||change.scope().startsWith("SKU:"+connection+":")&&change.scope().length()>42)||change.scope().length()>500||change.revision()<0)throw new IllegalArgumentException("Choose account, brand or a SKU in this store.");int updated=jdbc.update("UPDATE fba_replenishment_policies SET configuration=?::jsonb,revision=revision+1,updated_at=now(),updated_by=(SELECT id FROM app_users WHERE lower(email)=lower(?)) WHERE tenant_id=? AND scope_key=? AND revision=?",json.writeValueAsString(change.policy()),email,tenant,change.scope(),change.revision());if(updated==0&&change.revision()==0)updated=jdbc.update("INSERT INTO fba_replenishment_policies(tenant_id,scope_key,configuration,updated_by) VALUES (?,?,?::jsonb,(SELECT id FROM app_users WHERE lower(email)=lower(?))) ON CONFLICT DO NOTHING",tenant,change.scope(),json.writeValueAsString(change.policy()),email);if(updated!=1)throw FbaReplenishmentPlans.invalid("These settings changed. Reload before saving.");}
 @Transactional(readOnly=true) public List<Map<String,Object>> events(UUID tenant){scope(tenant);return decoded(jdbc.queryForList("SELECT id,name,start_date,end_date,configuration::text configuration,revision FROM fba_replenishment_events WHERE tenant_id=? ORDER BY start_date,id",tenant));}
 public record EventChange(UUID id,long revision,String name,LocalDate start,LocalDate end,String brand,String sku,UUID connection,boolean disabled,Double uplift,LocalDate previousStart,LocalDate previousEnd,String dateSource){}
 @Transactional public void saveEvent(UUID tenant,UUID connection,String email,EventChange change){scope(tenant);if(change==null||change.id()==null||change.revision()<0||change.name()==null||change.name().length()>160||change.connection()!=null&&!connection.equals(change.connection()))throw new IllegalArgumentException("Choose a verified event in this account/store.");new Event(change.id(),change.name(),change.start(),change.end(),change.uplift(),false,change.dateSource());
  if(change.previousStart()!=null&&(change.previousEnd()==null||change.previousEnd().isBefore(change.previousStart())||!change.previousEnd().isBefore(change.start())))throw new IllegalArgumentException("Use the corresponding previous event's verified dates.");
  // User-entered uplift is explicitly accepted evidence, not an invented historical comparison.
  var configuration=new LinkedHashMap<String,Object>();configuration.put("brand",Objects.toString(change.brand(),""));configuration.put("sku",Objects.toString(change.sku(),""));configuration.put("connection",change.connection());configuration.put("disabled",change.disabled());configuration.put("uplift",change.uplift());configuration.put("reliable",change.uplift()!=null&&!change.disabled());configuration.put("previousStart",change.previousStart());configuration.put("previousEnd",change.previousEnd());configuration.put("source",change.dateSource()==null?"User verified dates/adjustment":change.dateSource());
  int count=jdbc.update("UPDATE fba_replenishment_events SET name=?,start_date=?,end_date=?,configuration=?::jsonb,revision=revision+1,updated_at=now(),updated_by=(SELECT id FROM app_users WHERE lower(email)=lower(?)) WHERE tenant_id=? AND id=? AND revision=?",change.name(),change.start(),change.end(),json.writeValueAsString(configuration),email,tenant,change.id(),change.revision());if(count==0&&change.revision()==0)count=jdbc.update("INSERT INTO fba_replenishment_events(id,tenant_id,name,start_date,end_date,configuration,updated_by) VALUES (?,?,?,?,?,?::jsonb,(SELECT id FROM app_users WHERE lower(email)=lower(?))) ON CONFLICT DO NOTHING",change.id(),tenant,change.name(),change.start(),change.end(),json.writeValueAsString(configuration),email);if(count!=1)throw FbaReplenishmentPlans.invalid("This event changed. Reload before saving.");}
}
